        case .calibration: return snapshot.calibrationDelta
        case .reflectionDepth: return snapshot.reflectionDepthDelta
        }
    }

    private var reason: String? {
        snapshot.metricReasons[metric.rawValue]
    }

    private var positiveContributions: [MetricContribution] {
        contributions.filter { $0.direction == .positive }
    }

    private var negativeContributions: [MetricContribution] {
        contributions.filter { $0.direction == .negative }
    }

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    metricHeaderSection
                    changeSection
                    reasonSection

                    if contributions.isEmpty {
                        insufficientEvidenceSection
                    } else {
                        if !positiveContributions.isEmpty {
                            contributionSection(
                                title: "正向信号",
                                contributions: positiveContributions,
                                accentColor: DS.success
                            )
                        }
                        if !negativeContributions.isEmpty {
                            contributionSection(
                                title: "负向信号",
                                contributions: negativeContributions,
                                accentColor: DS.brick
                            )
                        }
                    }

                    trainingFocusSection
                }
                .padding(.horizontal, DS.pagePadding)
                .padding(.top, 16)
                .padding(.bottom, 40)
            }
            .pageBackground()
            .navigationTitle(metricTitle)
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button("完成") { dismiss() }
                }
            }
        }
    }

    private var metricHeaderSection: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text(metricNote)
                .font(.caption.weight(.semibold))
                .foregroundStyle(DS.mutedInk)
                .textCase(.uppercase)
                .tracking(0.5)

            HStack(alignment: .firstTextBaseline, spacing: 16) {
                Text(String(format: "%.1f", currentValue))
                    .font(.system(size: 34, weight: .bold, design: .rounded))
                    .foregroundStyle(DS.ink)

                if let previous = previousValue {
                    Text("上期 \(String(format: "%.1f", previous))")
                        .font(.subheadline.monospacedDigit())
                        .foregroundStyle(DS.mutedInk)
                }
            }
        }
        .padding(DS.cardInnerPadding)
        .background(DS.surface, in: RoundedRectangle(cornerRadius: DS.cornerRadius, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: DS.cornerRadius, style: .continuous)
                .stroke(DS.hairline, lineWidth: 1)
        )
    }

    private var changeSection: some View {
        VStack(alignment: .leading, spacing: 8) {
            SectionLabel("变化")
            HStack(spacing: 12) {
                if let delta = deltaValue {
                    HStack(spacing: 4) {
                        Image(systemName: delta >= 0 ? "arrow.up.right" : "arrow.down.right")
                            .font(.caption.weight(.semibold))
                        Text(String(format: "%+.1f", delta))
                            .font(.subheadline.monospacedDigit().weight(.semibold))
                    }
                    .foregroundStyle(delta >= 0 ? DS.success : DS.brick)
                } else {
                    Text("首次评估")
                        .font(.subheadline)
                        .foregroundStyle(DS.mutedInk)
                }
                Spacer()
                if let previous = previousValue {
                    Text("\(String(format: "%.1f", previous)) → \(String(format: "%.1f", currentValue))")
                        .font(.caption.monospacedDigit())
                        .foregroundStyle(DS.mutedInk)
                }
            }
        }
        .summarySurface()
    }

    @ViewBuilder
    private var reasonSection: some View {
        if let displayReason = growthMetricReasonDisplay(reason) {
            VStack(alignment: .leading, spacing: 8) {
                SectionLabel("判断依据")
                Text(displayReason)
                    .font(.subheadline)
                    .foregroundStyle(DS.ink)
                    .fixedSize(horizontal: false, vertical: true)
            }
            .summarySurface()
        } else if let fallback = growthMetricFallbackReason(reason: reason, contributions: contributions) {
            VStack(alignment: .leading, spacing: 8) {
                SectionLabel("判断依据")
                Text(fallback)
                    .font(.subheadline)
                    .foregroundStyle(DS.mutedInk)
                    .fixedSize(horizontal: false, vertical: true)
            }
            .summarySurface()
        }
    }

    private var insufficientEvidenceSection: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text("证据不足")
                .font(.headline)
                .foregroundStyle(DS.ink)
            Text("这个指标还没有足够的已接受证据来展示变化来源。继续完成复盘，系统会逐步积累可引用的证据。")
                .font(.subheadline)
                .foregroundStyle(DS.mutedInk)
                .fixedSize(horizontal: false, vertical: true)
        }
        .summarySurface()
    }

    private func contributionSection(title: String, contributions: [MetricContribution], accentColor: Color) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            SectionLabel(title)
            ForEach(contributions) { contribution in
                ContributionRow(
                    contribution: contribution,
                    accentColor: accentColor,
                    onSelect: {
                        onSelectContribution(contribution)
                        dismiss()
                    },
                    onUpdateFeedback: { feedback in
                        onUpdateContributionFeedback(contribution, feedback)
                    }
                )
            }
        }
    }

    @ViewBuilder
    private var trainingFocusSection: some View {
        if let focus = snapshot.nextTrainingFocus, !focus.isEmpty {
            VStack(alignment: .leading, spacing: 10) {
                SectionLabel("下一步训练重点")
                Text(focus)
                    .font(.subheadline)
                    .foregroundStyle(DS.ink)
                    .fixedSize(horizontal: false, vertical: true)
            }
            .padding(DS.cardInnerPadding)
            .background(DS.accent.opacity(0.06), in: RoundedRectangle(cornerRadius: DS.cornerRadius, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: DS.cornerRadius, style: .continuous)
                    .stroke(DS.accent.opacity(0.15), lineWidth: 1)
            )
        }
    }
}

private struct ContributionRow: View {
    let contribution: MetricContribution
    let accentColor: Color
    let onSelect: () -> Void
    let onUpdateFeedback: (MetricContributionFeedback) -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                RoundedRectangle(cornerRadius: 2)
                    .fill(rowAccentColor)
                    .frame(width: 3, height: 32)

                VStack(alignment: .leading, spacing: 4) {
                    HStack(spacing: 6) {
                        Text(contribution.title)
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(DS.ink)
                        if isMarkedInaccurate {
                            Text("不准确")
                                .font(.caption2.weight(.semibold))
                                .foregroundStyle(DS.brick)
                                .padding(.horizontal, 6)
                                .padding(.vertical, 2)
                                .background(DS.brick.opacity(0.08), in: Capsule())
                        }
                    }
                    Text(contribution.reason)
                        .font(.caption)
                        .foregroundStyle(DS.mutedInk)
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 8)

                Image(systemName: "arrow.up.right")
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(DS.mutedInk.opacity(0.7))
            }

            HStack(spacing: 12) {
                Label(sourceTypeLabel, systemImage: sourceTypeIcon)
                    .font(.caption)
                    .foregroundStyle(DS.mutedInk)
                Label(String(contribution.sourceDailyEntryId.uuidString.prefix(8)), systemImage: "calendar")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(DS.mutedInk)
                if !contribution.sourceId.isEmpty {
                    Text("证据 \(contribution.sourceId.prefix(8))")
                        .font(.caption.monospacedDigit())
                        .foregroundStyle(DS.mutedInk)
                }
                Spacer()
                feedbackButton
                Text(String(format: "%+.2f", contribution.delta))
                    .font(.caption.monospacedDigit().weight(.semibold))
                    .foregroundStyle(rowAccentColor)
            }
        }
        .contentShape(Rectangle())
        .onTapGesture(perform: onSelect)
        .summarySurface()

// MARK: - Project merge audit display helpers

func testMergeAuditDisplayLines_emptyHistoryProducesNoLines() {
    let lines = mergeAuditDisplayLines(from: [])
    XCTAssertTrue(lines.isEmpty, "empty merge history should produce no display lines")
}

func testMergeAuditDisplayLines_whitespaceOnlyHistoryIsIgnored() {
    let lines = mergeAuditDisplayLines(from: ["  ", "\t", "\n ", ""])
    XCTAssertTrue(lines.isEmpty, "whitespace-only entries should be filtered out")
}

func testMergeAuditDisplayLines_nonEmptyHistoryIsTrimmedAndPreserved() {
    let lines = mergeAuditDisplayLines(from: ["  merged from X  ", "archived source Y "])
    XCTAssertEqual(lines, ["merged from X", "archived source Y"])
}

func testCandidateEvidenceSummary_includesCountAndCompactRefs() {
    let candidate = ProjectMergeCandidate(
        sourceProjectId: UUID(),
        targetProjectId: UUID(),
        reason: "overlap",
        overlappingEvidenceRefs: ["abc12345-6789", "def67890-1234", "ghi11111-2222"]
    )
    let summary = candidateEvidenceSummary(candidate)
    XCTAssertTrue(summary.contains("3"), "should contain evidence count")
    XCTAssertTrue(summary.contains("abc12345"), "should contain compact ref preview")
}

func testCandidateEvidenceSummary_emptyRefsShowsCountOnly() {
    let candidate = ProjectMergeCandidate(
        sourceProjectId: UUID(),
        targetProjectId: UUID(),
        reason: "overlap",
        overlappingEvidenceRefs: []
    )
    let summary = candidateEvidenceSummary(candidate)
    XCTAssertTrue(summary.contains("0"), "should show zero count")
}

func testCandidateConsequenceLine_doesNotClaimLinksMovedOrSourceDeleted() {
    let line = candidateConsequenceLine()
    XCTAssertFalse(line.contains("删除"), "must not claim source is deleted")
    XCTAssertFalse(line.contains("移动"), "must not claim links are moved")
    XCTAssertTrue(line.contains("归档"), "should mention source is archived")
    XCTAssertTrue(line.contains("保留"), "should mention evidence links are retained")
}

// MARK: - Growth report drilldown helpers

private func makeContribution(
    metric: GrowthMetric = .clarity,
    direction: MetricContributionDirection,
    delta: Double,
    title: String = "test",
    reason: String = "reason",
    sourceId: String = "src123"
) -> MetricContribution {
    MetricContribution(
        id: UUID(),

            id: UUID(),
            snapshotId: UUID(),
            metric: metric,
            direction: direction,
            delta: delta,
            title: title,
            reason: reason,
            sourceType: .dailyEntry,
            sourceId: sourceId,
            sourceDailyEntryId: UUID(),
            userFeedback: .none,
            candidateStatus: .accepted,
            createdAt: Date(),
            updatedAt: Date()
        )
    }

    func testGrowthContributionCountSummary_countsPositiveAndNegative() {
        let contributions = [
            makeContribution(direction: .positive, delta: 0.3),
            makeContribution(direction: .positive, delta: 0.1),
            makeContribution(direction: .negative, delta: -0.2),
        ]
        let summary = growthContributionCountSummary(contributions)
        XCTAssertTrue(summary.contains("2"), "should contain positive count")
        XCTAssertTrue(summary.contains("1"), "should contain negative count")
    }

    func testGrowthContributionCountSummary_emptyContributions() {
        let summary = growthContributionCountSummary([])
        XCTAssertTrue(summary.contains("0"), "should show zero counts")
    }

    func testGrowthLeadingContribution_choosesLargestAbsoluteDelta() {
        let contributions = [
            makeContribution(direction: .positive, delta: 0.2, title: "small"),
            makeContribution(direction: .negative, delta: -0.8, title: "large negative"),
            makeContribution(direction: .positive, delta: 0.5, title: "medium"),
        ]
        let leading = growthLeadingContribution(contributions)
        XCTAssertEqual(leading?.title, "large negative", "should pick largest absolute delta")
    }

    func testGrowthLeadingContribution_emptyReturnsNil() {
        let leading = growthLeadingContribution([])
        XCTAssertNil(leading, "empty contributions should return nil")
    }

    func testGrowthMetricReasonDisplay_trimsWhitespace() {
        let display = growthMetricReasonDisplay("  实际原因  ")
        XCTAssertEqual(display, "实际原因", "should trim whitespace")
    }

    func testGrowthMetricReasonDisplay_emptyStringReturnsNil() {
        let display = growthMetricReasonDisplay("  ")
        XCTAssertNil(display, "whitespace-only reason should return nil")
    }

    func testGrowthMetricReasonDisplay_nilInputReturnsNil() {
        let display = growthMetricReasonDisplay(nil)
        XCTAssertNil(display, "nil reason should return nil")
    }

    func testGrowthFallbackReason_presentWhenReasonMissingAndContributionsExist() {
        let contributions = [
            makeContribution(direction: .positive, delta: 0.3),
        ]
        let fallback = growthMetricFallbackReason(reason: nil, contributions: contributions)
        XCTAssertNotNil(fallback, "should provide fallback when reason is missing but contributions exist")
        XCTAssertTrue(fallback!.contains("贡献"), "fallback should mention contributions")
    }

    func testGrowthFallbackReason_absentWhenReasonMissingAndNoContributions() {
        let fallback = growthMetricFallbackReason(reason: nil, contributions: [])
        XCTAssertNil(fallback, "no fallback when no reason and no contributions")
    }

    func testGrowthFallbackReason_absentWhenReasonPresent() {
        let fallback = growthMetricFallbackReason(reason: "有原因", contributions: [
            makeContribution(direction: .positive, delta: 0.3),
        ])
        XCTAssertNil(fallback, "no fallback when reason already exists")
    }

    func testGrowthMetricDisplayTitle_returnsCorrectTitle() {
        XCTAssertEqual(growthMetricDisplayTitle(.clarity), "清晰度")
        XCTAssertEqual(growthMetricDisplayTitle(.valueJudgment), "价值判断")
        XCTAssertEqual(growthMetricDisplayTitle(.executionReliability), "执行可靠性")
        XCTAssertEqual(growthMetricDisplayTitle(.calibration), "校准")
        XCTAssertEqual(growthMetricDisplayTitle(.reflectionDepth), "反思深度")
    }
}

